{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Ofloxacin, a fluoroquinolone with the same 4-oxo-3-carboxylic acid core, has an absolute oral bioavailability of 91% (lower 95% CI 74.1%) in patients, directly supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Trovafloxacin, a structurally related fluoroquinolone, has a mean absolute oral bioavailability of 87.6% in healthy subjects, supporting high oral absorption for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Moxifloxacin, a fluoroquinolone with an N-1 cyclopropyl group and C-7 basic amine, is almost completely absorbed with an absolute bioavailability of 86–92% in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Levofloxacin, a close fluoroquinolone analogue, is well absorbed from the gastrointestinal tract with bioavailability approaching 100%, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Finafloxacin, an N-1 cyclopropyl fluoroquinolone, shows absolute oral bioavailability ranging from about 60% to essentially complete, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Even norfloxacin, a less completely absorbed fluoroquinolone, has reported absolute bioavailability values of 35–70%, all above the 20% threshold, reinforcing that this quinolone class is generally high-bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a fluoroquinolone antibiotic with the characteristic 4-oxo-3-carboxylic acid core, N-1 fluorocyclopropyl, 8-chloro, and C-7 basic amine substituents. Multiple high-transfer experimental records from close fluoroquinolone analogues—ofloxacin, levofloxacin, trovafloxacin, moxifloxacin, and finafloxacin—show absolute oral bioavailability mostly above 85%, and even the least absorbed analogue, norfloxacin, exceeds the 20% threshold. The evidence strongly supports high oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the exact query molecule.",
    "Potential effects of formulation, dose, food, or disease state on the query's bioavailability are not directly addressed by the retrieved records.",
    "The query's unique 3-amino-spirocyclopropyl piperidine substituent is not represented by an exact analogue, though the fluoroquinolone core and overall physicochemical features align with high-bioavailability members of the class."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

